    def place(
        self, customer: str, /, drink: str = "espresso", quantity: int = 1,
        *extras: OrderLine, priority: bool = False,
        on_ready: Callable[[Order], None] | None = None, **notes: str,
    ) -> Order:
        order = Order(customer, [OrderLine(drink, quantity), *extras], notes=notes)
